# This file is not generated by Stainless and is preserved across codegen runs.
# It marks generated CDN tests that fail against the mock server because of a
# known spec issue. Each entry names the Jira task that fixes it; remove the
# entry when that task is done. strict=True fails the run once a marked test
# passes again, so a fixed entry cannot be forgotten.
from __future__ import annotations

from pathlib import Path

import pytest

# The target config oneOf variants overlap, so the mock rejects some minimal `config={}` calls.
_TARGETS = "CDP-2739: logs uploader target config oneOf variants are not mutually exclusive"
# Overload numbers follow the storage_type order in the spec.
_TARGETS_OVERLOADS = {"create": (4, 5, 6, 9, 10), "replace": (1,)}
# The mock answers with the plain-list variant while the SDK expects the paginated one.
_PRESETS = "GCLOUD2-30511: presets list response is a oneOf of a plain and a paginated list"

# (test file relative to this directory, test function) -> reason
_KNOWN_FAILURES: dict[tuple[str, str], str] = {
    **{
        ("logs_uploader/test_targets.py", f"test_{kind}_{method}_overload_{n}"): _TARGETS
        for kind in ("method", "raw_response", "streaming_response")
        for method, overloads in _TARGETS_OVERLOADS.items()
        for n in overloads
    },
    **{
        ("test_presets.py", name): _PRESETS
        for name in (
            "test_method_list",
            "test_method_list_with_all_params",
            "test_raw_response_list",
            "test_streaming_response_list",
        )
    },
}

_HERE = Path(__file__).parent


def pytest_collection_modifyitems(items: list[pytest.Item]) -> None:
    for item in items:
        if not item.path.is_relative_to(_HERE) or not isinstance(item, pytest.Function):
            continue
        reason = _KNOWN_FAILURES.get((item.path.relative_to(_HERE).as_posix(), item.originalname))
        if reason:
            item.add_marker(pytest.mark.xfail(reason=reason, strict=True))
